Given an unsorted array arr[] with both positive and negative elements, find the smallest positive number missing from the array.Examples:Input: arr[] = [2, -3, 4, 1, 1, 7]Output: 3Explanation: 3 is the smallest positive number missing from the array.Input: arr[] = [5, 3, 2, 5, 1]Output: 4Explanation: 4 is the smallest positive number missing from the array.Input: arr[] = [-8, 0, -1, -4, -3]Output: 1 Explanation: 1 is the smallest positive number missing from the array.Try It YourselfTable of Content[Naive approach] By Sorting - O(n*log n) Time and O(1) Space[Better approach] Using Visited Array - O(n) Time and O(n) Space[Expected Approach] Using Cycle Sort - O(n) Time and O(1) Space[Alternate Approach - 1] By Negating Array Elements – O(n) Time and O(1) Space[Alternate Approach - 2] By Marking Indices – O(n) Time and O(1) Space[Naive approach] By Sorting - O(n*log n) Time and O(1) SpaceThe idea is to sort the array and assume the missing number as 1. Now, iterate over the array and for each element arr[i],If arr[i] == missing number, then increment missing number by 1.If arr[i] < missing number, then continue to search for the missing number.If arr[i] > missing number, then break and return the missing number 
            C++

    #include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int missingNumber(vector<int> &arr) {

    sort(arr.begin(), arr.end());
    int res = 1;
    for (int i = 0; i < arr.size(); i++) {

        // If we have found 'res' in the array,
        // 'res' is no longer missing, so increment it
        if (arr[i] == res) 
            res++;

        // If the current element is larger than 'res',
        // 'res' cannot be found in the array,
        // so it is our final answer
        else if (arr[i] > res) 
            break;
    }
    return res;
}

int main() {
    vector<int> arr = {2, -3, 4, 1, 1, 7};

    cout << missingNumber(arr);
    return 0;
}


